```java
int vies = 3;
while (true) {
    String ligne = IO.readln();
    if (ligne == null || ligne.equals("stop")) break;
    String[] mots = ligne.trim().split("\\s+");     // mots[0] = commande, mots[1] = argument
    switch (mots[0]) {
        case "perd" -> vies -= Integer.parseInt(mots[1]);
        case "vies" -> IO.println("Vies : " + vies);
        default -> IO.println("?");
    }
}
```
